var_f:			dcb.b 200, 32		; String * 200 (n spaces)
			dc.b 0
			even
			dc.b 3			; capacity
var_f3:			dcb.b 3, 32		; String * 3 (n spaces)
			dc.b 0
			even
			dc.b 255			; capacity
var_rep_rep:			ds.b 256
			even
var_lenof_lenof:			dc.w 0
var_i:			dc.w 0
ad_arr_names:			dc.w (arr_names)&$FFFF, (0)&$FFFF, (0)&$FFFF, (10)&$FFFF, (1)&$FFFF, (13)&$FFFF		; array as an argument
			dc.b 8			; capacity
var_r_nm:			ds.b 9
