var_v:			ds.b 41
			even
var_t:			dc.w 0
var_bad:			dc.w 0
p_chk_rs:			dc.l 0
var_chk_got:			dc.w 0
var_chk_want:			dc.w 0
p_rep_rs:			dc.l 0
			dc.b 255			; capacity
var_rep_c:			ds.b 256
			even
var_rep_n:			dc.w 0
p_lenof_rs:			dc.l 0
			dc.b 255			; capacity
var_lenof_x:			ds.b 256
			even
p_fill_rs:			dc.l 0
