			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_names		equ ntc_bss + 0		; 130 bytes
arr_wide		equ ntc_bss + 130		; 303 bytes
arr_huge		equ ntc_bss + 434		; 768 bytes
pa_d		equ ntc_bss + 1202		; 12 bytes
pa_parts		equ ntc_bss + 1214		; 12 bytes
pa_d_data		equ ntc_bss + 1226		; 33 bytes
pa_parts_data		equ ntc_bss + 1260		; 112 bytes
pa_setel_a		equ ntc_bss + 1372		; 12 bytes
ntc_bss_size	equ 1384
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
